<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { lazyStrings } from '@/strings';
import type { LmParameters } from '@/01-models/types';
import { RotateCcwIcon, XIcon } from 'lucide-vue-next';
import { hasLmParameterOverrides } from '@/utils/lm-parameters';

const props = defineProps<{
  modelValue?: LmParameters,
  inheritanceLabel?: string,
}>();

const emit = defineEmits<{
  (e: 'update:modelValue', value: LmParameters): void,
}>();

const defaultParams: LmParameters = {
  temperature: undefined,
  topP: undefined,
  maxCompletionTokens: undefined,
  presencePenalty: undefined,
  frequencyPenalty: undefined,
  stop: undefined,
  reasoning: { effort: undefined },
};

const params = computed<LmParameters>({
  get: () => ({ ...defaultParams, ...props.modelValue }),
  set: (val) => emit('update:modelValue', val),
});

const stopSequencesRaw = ref('');
const stopJsonErrorType = ref<'array_of_strings' | 'invalid_json' | null>(null);
const stopJsonError = computed(() => {
  switch (stopJsonErrorType.value) {
  case 'array_of_strings':
    return lazyStrings.LmParametersEditor__must_be_an_array_of_strings();
  case 'invalid_json':
    return lazyStrings.LmParametersEditor__invalid_json();
  case null:
    return null;
  default: {
    const _ex: never = stopJsonErrorType.value;
    return _ex;
  }
  }
});

watch(() => params.value.stop, (newVal) => {
  const str = newVal ? JSON.stringify(newVal) : '';
  if (str !== stopSequencesRaw.value && stopJsonErrorType.value === null) {
    stopSequencesRaw.value = str;
  }
}, { immediate: true });

// Keep the key switches below exhaustive. Adding an LM parameter must stop
// typechecking until its clear and assignment semantics are implemented; this
// deliberately prevents a future refactor from silently ignoring the field.
function updateParam<K extends keyof LmParameters>({ key, value }: { key: K, value: LmParameters[K] }) {
  const newParams: LmParameters = { ...params.value };
  if (value === undefined || value === null || (value as unknown) === '' || (typeof value === 'number' && isNaN(value))) {
    switch (key) {
    case 'reasoning':
      newParams.reasoning = { effort: undefined };
      break;
    case 'temperature':
    case 'topP':
    case 'maxCompletionTokens':
    case 'presencePenalty':
    case 'frequencyPenalty':
    case 'stop':
      delete newParams[key];
      break;
    default: {
      const _ex: never = key;
      throw new Error(`Unhandled parameter key: ${_ex}`);
    }
    }
  } else {
    switch (key) {
    case 'reasoning':
      newParams.reasoning = value as LmParameters['reasoning'];
      break;
    case 'temperature':
      newParams.temperature = value as LmParameters['temperature'];
      break;
    case 'topP':
      newParams.topP = value as LmParameters['topP'];
      break;
    case 'maxCompletionTokens':
      newParams.maxCompletionTokens = value as LmParameters['maxCompletionTokens'];
      break;
    case 'presencePenalty':
      newParams.presencePenalty = value as LmParameters['presencePenalty'];
      break;
    case 'frequencyPenalty':
      newParams.frequencyPenalty = value as LmParameters['frequencyPenalty'];
      break;
    case 'stop':
      newParams.stop = value as LmParameters['stop'];
      break;
    default: {
      const _ex: never = key;
      throw new Error(`Unhandled parameter key: ${_ex}`);
    }
    }
  }
  params.value = newParams;
}

function handleStopInput({ value }: { value: string }) {
  stopSequencesRaw.value = value;
  if (!value.trim()) {
    updateParam({ key: 'stop', value: undefined });
    stopJsonErrorType.value = null;
    return;
  }
  try {
    const parsed = JSON.parse(value);
    if (Array.isArray(parsed) && parsed.every(item => typeof item === 'string')) {
      updateParam({ key: 'stop', value: parsed.length > 0 ? parsed : undefined });
      stopJsonErrorType.value = null;
    } else {
      stopJsonErrorType.value = 'array_of_strings';
    }
  } catch (e) {
    stopJsonErrorType.value = 'invalid_json';
  }
}

function reset() {
  params.value = { ...defaultParams };
  stopSequencesRaw.value = '';
  stopJsonErrorType.value = null;
}

// This exhaustive switch is also a compile-time review gate for new parameters.
// Do not replace it with a partial list of property checks.
const isOverridden = ({ key }: { key: keyof LmParameters }) => {
  switch (key) {
  case 'reasoning':
    return params.value.reasoning.effort !== undefined;
  case 'temperature':
  case 'topP':
  case 'maxCompletionTokens':
  case 'presencePenalty':
  case 'frequencyPenalty':
  case 'stop':
    return params.value[key] !== undefined;
  default: {
    const _ex: never = key;
    throw new Error(`Unhandled parameter key: ${_ex}`);
  }
  }
};



defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/8ee156c6625622294462f7b2fa29eb80f826afe0e2c7be9c698da3e15c1029ef.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
import "virtual:naidan-tailwind-css-module/f9004e4bacdf86afb575355f988f793b2afd745c3bac6d2f33d6f5ff0aadcaee.js";
</script>

<template>
  <div tw-class="space-y-6">
    <div tw-class="flex items-center justify-between">
      <div tw-class="flex items-center gap-2">
        <h3 tw-class="text-xs font-bold text-gray-400 uppercase tracking-widest">{{ lazyStrings.LmParametersEditor__lm_parameters() }}</h3>
        <span tw-class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 border border-blue-100 dark:border-blue-800">
          {{ inheritanceLabel ?? lazyStrings.LmParametersEditor__empty_fields_use_provider_defaults() }}
        </span>
      </div>
      <button
        v-if="hasLmParameterOverrides({ lmParameters: params })"
        @click="reset"
        tw-class="text-[10px] font-bold text-gray-400 hover:text-blue-500 flex items-center gap-1 transition-colors"
      >
        <RotateCcwIcon tw-class="w-3 h-3" />
        {{ lazyStrings.LmParametersEditor__reset_all() }}
      </button>
    </div>

    <div tw-class="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-8">
      <!-- Temperature -->
      <div :tw-class="['space-y-3', { 'opacity-60': !isOverridden({ key: 'temperature' }) }]">
        <div tw-class="flex justify-between items-center">
          <label :tw-class="['text-xs font-bold flex items-center gap-1.5', isOverridden({ key: 'temperature' }) ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500']">
            {{ lazyStrings.LmParametersEditor__temperature() }}
            <span v-if="isOverridden({ key: 'temperature' })" tw-class="w-1 h-1 rounded-full bg-blue-500 animate-pulse"></span>
          </label>
          <div tw-class="flex items-center gap-2">
            <input
              type="number" step="0.1" min="0" max="2"
              :value="params.temperature"
              @input="e => updateParam({ key: 'temperature', value: (e.target as HTMLInputElement).valueAsNumber })"
              :placeholder="inheritanceLabel ?? lazyStrings.LmParametersEditor__default()"
              tw-class="w-16 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg px-2 py-1 text-[11px] font-bold text-right outline-none focus:border-blue-500 transition-all"
            />
            <button v-if="isOverridden({ key: 'temperature' })" @click="updateParam({ key: 'temperature', value: undefined })" tw-class="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded text-gray-400"><XIcon tw-class="w-3 h-3"/></button>
          </div>
        </div>
        <input
          type="range" min="0" max="2" step="0.01"
          :value="params.temperature ?? 1"
          @input="e => updateParam({ key: 'temperature', value: parseFloat((e.target as HTMLInputElement).value) })"
          tw-class="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-blue-600"
        />
      </div>

      <!-- Top P -->
      <div :tw-class="['space-y-3', { 'opacity-60': !isOverridden({ key: 'topP' }) }]">
        <div tw-class="flex justify-between items-center">
          <label :tw-class="['text-xs font-bold flex items-center gap-1.5', isOverridden({ key: 'topP' }) ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500']">
            {{ lazyStrings.LmParametersEditor__top_p() }}
            <span v-if="isOverridden({ key: 'topP' })" tw-class="w-1 h-1 rounded-full bg-blue-500 animate-pulse"></span>
          </label>
          <div tw-class="flex items-center gap-2">
            <input
              type="number" step="0.01" min="0" max="1"
              :value="params.topP"
              @input="e => updateParam({ key: 'topP', value: (e.target as HTMLInputElement).valueAsNumber })"
              :placeholder="inheritanceLabel ?? lazyStrings.LmParametersEditor__default()"
              tw-class="w-16 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg px-2 py-1 text-[11px] font-bold text-right outline-none focus:border-blue-500 transition-all"
            />
            <button v-if="isOverridden({ key: 'topP' })" @click="updateParam({ key: 'topP', value: undefined })" tw-class="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded text-gray-400"><XIcon tw-class="w-3 h-3"/></button>
          </div>
        </div>
        <input
          type="range" min="0" max="1" step="0.01"
          :value="params.topP ?? 1"
          @input="e => updateParam({ key: 'topP', value: parseFloat((e.target as HTMLInputElement).value) })"
          tw-class="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-blue-600"
        />
      </div>

      <!-- Max Tokens -->
      <div :tw-class="['space-y-3', { 'opacity-60': !isOverridden({ key: 'maxCompletionTokens' }) }]">
        <div tw-class="flex justify-between items-center">
          <label :tw-class="['text-xs font-bold flex items-center gap-1.5', isOverridden({ key: 'maxCompletionTokens' }) ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500']">
            {{ lazyStrings.LmParametersEditor__max_tokens() }}
            <span v-if="isOverridden({ key: 'maxCompletionTokens' })" tw-class="w-1 h-1 rounded-full bg-blue-500 animate-pulse"></span>
          </label>
          <div tw-class="flex items-center gap-2">
            <input
              type="number" min="1"
              :value="params.maxCompletionTokens"
              @input="e => updateParam({ key: 'maxCompletionTokens', value: (e.target as HTMLInputElement).valueAsNumber })"
              :placeholder="inheritanceLabel ?? lazyStrings.LmParametersEditor__default()"
              tw-class="w-24 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg px-2 py-1 text-[11px] font-bold text-right outline-none focus:border-blue-500 transition-all"
            />
            <button v-if="isOverridden({ key: 'maxCompletionTokens' })" @click="updateParam({ key: 'maxCompletionTokens', value: undefined })" tw-class="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded text-gray-400"><XIcon tw-class="w-3 h-3"/></button>
          </div>
        </div>
      </div>

      <!-- Presence Penalty -->
      <div :tw-class="['space-y-3', { 'opacity-60': !isOverridden({ key: 'presencePenalty' }) }]">
        <div tw-class="flex justify-between items-center">
          <label :tw-class="['text-xs font-bold flex items-center gap-1.5', isOverridden({ key: 'presencePenalty' }) ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500']">
            {{ lazyStrings.LmParametersEditor__presence_penalty() }}
            <span v-if="isOverridden({ key: 'presencePenalty' })" tw-class="w-1 h-1 rounded-full bg-blue-500 animate-pulse"></span>
          </label>
          <div tw-class="flex items-center gap-2">
            <input
              type="number" step="0.1" min="-2" max="2"
              :value="params.presencePenalty"
              @input="e => updateParam({ key: 'presencePenalty', value: (e.target as HTMLInputElement).valueAsNumber })"
              :placeholder="inheritanceLabel ?? lazyStrings.LmParametersEditor__default()"
              tw-class="w-16 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg px-2 py-1 text-[11px] font-bold text-right outline-none focus:border-blue-500 transition-all"
            />
            <button v-if="isOverridden({ key: 'presencePenalty' })" @click="updateParam({ key: 'presencePenalty', value: undefined })" tw-class="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded text-gray-400"><XIcon tw-class="w-3 h-3"/></button>
          </div>
        </div>
        <input
          type="range" min="-2" max="2" step="0.01"
          :value="params.presencePenalty ?? 0"
          @input="e => updateParam({ key: 'presencePenalty', value: parseFloat((e.target as HTMLInputElement).value) })"
          tw-class="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-blue-600"
        />
      </div>

      <!-- Stop Sequences -->
      <div :tw-class="['space-y-3 col-span-1 md:col-span-2', { 'opacity-60': !isOverridden({ key: 'stop' }) }]">
        <div tw-class="flex justify-between items-center">
          <label :tw-class="['text-xs font-bold flex items-center gap-1.5', isOverridden({ key: 'stop' }) ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500']">
            {{ lazyStrings.LmParametersEditor__stop_sequences_json_array() }}
            <span v-if="isOverridden({ key: 'stop' })" tw-class="w-1 h-1 rounded-full bg-blue-500 animate-pulse"></span>
          </label>
          <button v-if="isOverridden({ key: 'stop' })" @click="updateParam({ key: 'stop', value: undefined })" tw-class="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded text-gray-400 flex items-center gap-1 text-[10px] font-bold">
            <XIcon tw-class="w-3 h-3"/> {{ lazyStrings.LmParametersEditor__reset_to_default() }}
          </button>
        </div>
        <textarea
          :value="stopSequencesRaw"
          @input="e => handleStopInput({ value: (e.target as HTMLTextAreaElement).value })"
          rows="2"
          :tw-class="['w-full bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl px-4 py-2 text-xs font-mono font-bold outline-none focus:border-blue-500 transition-all shadow-sm resize-none', { 'border-red-500 focus:border-red-500': stopJsonError }]"
          placeholder='["\n", "User:"]'
        ></textarea>
        <p v-if="stopJsonError" tw-class="text-[9px] text-red-500 font-bold ml-1">{{ stopJsonError }}</p>
      </div>
    </div>
  </div>
</template>
